begin;

create or replace function public.pin_live_session_product(p_session_id uuid,p_product_id uuid,p_featured_variant_id uuid,p_idempotency_key uuid)returns jsonb language plpgsql security definer set search_path=public as $$declare actor uuid:=auth.uid();fingerprint text;prior public.live_commerce_commands;c record;p public.products;v public.marketplace_product_variants;r public.live_session_products;result jsonb;resolved_offer_id uuid;resolved_offer_bps integer;mode text;bps integer;begin if actor is null or p_session_id is null or p_product_id is null or p_idempotency_key is null then raise exception using message='live_commerce_invalid_input';end if;fingerprint:=encode(extensions.digest(concat_ws('|','pin',p_session_id,p_product_id,coalesce(p_featured_variant_id::text,'')),'sha256'),'hex');perform pg_advisory_xact_lock(hashtextextended(actor::text||':'||p_idempotency_key::text,0));select*into prior from public.live_commerce_commands where actor_id=actor and idempotency_key=p_idempotency_key;if found then if prior.request_fingerprint<>fingerprint then raise exception using message='live_commerce_idempotency_conflict';end if;return prior.result_json;end if;select*into c from public.live_commerce_host_context(p_session_id);perform pg_advisory_xact_lock(hashtextextended('live-pin:'||p_session_id,0));select*into p from public.products where id=p_product_id;if not found or p.status<>'active'or p.moderation_status<>'approved'or p.product_type<>'physical'or p.currency<>'BDAG'or p.deleted_at is not null or not exists(select 1 from public.marketplace_stores st join public.marketplace_sellers ms on ms.user_id=st.seller_id where st.id=p.store_id and st.seller_id=p.seller_id and st.status='active'and ms.status='approved')then raise exception using message='live_commerce_product_unavailable';end if;if p.seller_id=actor then mode:='own_product';bps:=0;else select offer_id,commission_bps into resolved_offer_id,resolved_offer_bps from public.marketplace_resolve_live_affiliate_offer(p.id,actor);if not found then raise exception using message='live_affiliate_not_authorized';end if;mode:='affiliate_product';bps:=resolved_offer_bps;end if;if p_featured_variant_id is not null and not exists(select 1 from public.marketplace_product_variants where id=p_featured_variant_id and product_id=p.id and status='active'and archived_at is null)then raise exception using message='live_commerce_invalid_variant';end if;if not exists(select 1 from public.marketplace_product_variants x join public.marketplace_inventory_levels i on i.variant_id=x.id where x.product_id=p.id and x.status='active'and x.archived_at is null and i.on_hand>i.reserved)then raise exception using message='live_commerce_out_of_stock';end if;select*into r from public.live_session_products where session_id=p_session_id and product_id=p.id and status='active';if not found then if(select count(*)from public.live_session_products where session_id=p_session_id and status='active')>=20 then raise exception using message='live_commerce_pin_limit';end if;insert into public.live_session_products(session_id,host_id,seller_id,store_id,product_id,featured_variant_id,is_featured,position,commerce_mode,creator_commission_bps,affiliate_offer_id)values(p_session_id,actor,p.seller_id,p.store_id,p.id,p_featured_variant_id,false,(select count(*)from public.live_session_products where session_id=p_session_id and status='active'),mode,bps,resolved_offer_id)returning*into r;end if;result:=jsonb_build_object('id',r.id,'status',r.status,'is_featured',r.is_featured,'commerce_mode',r.commerce_mode,'creator_commission_bps',r.creator_commission_bps);insert into public.live_commerce_commands(actor_id,session_id,command_type,idempotency_key,request_fingerprint,result_json)values(actor,p_session_id,'pin',p_idempotency_key,fingerprint,result);return result;end$$;

revoke all on function public.pin_live_session_product(uuid,uuid,uuid,uuid)
  from public, anon;
grant execute on function public.pin_live_session_product(uuid,uuid,uuid,uuid)
  to authenticated, service_role;

commit;

